EDITS = {'CHANGELOG.md': [('lines 1-2', '# Changelog\n\n', '# Changelog\n\n## v0.6.0 — 2026-10-28\n\n**An anchor may carry a gameplay event.** The factory\'s walker, of a score location: "gameplay events or something\nthat doesn\'t mean much for level factory but is part of what would trigger police coming or stuff like that for the\ndispatch layer", "they could mean nothing, but they could also be ingested/used by the gameplay layer", and of the\nzones a player stands in, "we just have the event that we send (without spamming/rate limiting)". So an event is\nDATA, never behaviour Dispatch runs: `anchors.event_block` reads an anchor\'s `event` -- a dotted name (`alarm.*`,\n`score.*`, `zone.*`), `fires` (`on_touch`, `on_enter`, `on_exit`; default `on_touch`), `repeat` (`edge`: once when it\nbecomes true, not again until it has been false; or `once`; default `edge`), and the real alarm\'s `audible` where\nthere is one -- and `build_anchor_registry` and the anchor\'s node metadata carry it. An anchor without one is\nunchanged, so every package without events is byte for byte what it was. A block naming an event outside the\nvocabulary, or a firing rule not in it, raises: a consumer could not read it as it was meant. No heat, timer or\nmission end anywhere: those are the game\'s. `tests/test_events.py` (new; fails on 0.5.4).\n\n')], 'VERSION': [('lines 1-1', '0.5.4\n', '0.6.0\n')], 'dispatch/__init__.py': [('lines 14-14', '__version__ = "0.5.4"\n', '__version__ = "0.6.0"\n')], 'dispatch/anchors.py': [('lines 102-103', '\ndef required_authority_for(anchor: Anchor) -> str:\n', '\n#: GAMEPLAY EVENTS (0.6.0, the factory\'s roadmap 323). An anchor may carry an EVENT: data a game may ingest or\n#: ignore, never behaviour Dispatch runs. The factory\'s walker: "they could mean nothing, but they could also be\n#: ingested/used by the gameplay layer", and of zones a player stands in, "we don\'t do that, we just have the event\n#: that we send (without spamming/rate limiting)". So a block names the event and HOW it fires, and nothing about what\n#: follows -- no heat, timer or mission end:\n#:   event   a dotted name, `alarm.*`, `score.*` or `zone.*`\n#:   fires   `on_touch` (a fixture is used), `on_enter` / `on_exit` (a zone)\n#:   repeat  `edge` -- once when the condition becomes true, not again until it has been false (standing in a zone\n#:           sends one event, not one a frame) -- or `once`, once per mission\n#:   audible a fact about the real alarm, where there is one\nEVENT_PREFIXES = ("alarm.", "score.", "zone.")\nEVENT_FIRES = ("on_touch", "on_enter", "on_exit")\nEVENT_REPEAT = ("edge", "once")\n\n\ndef event_block(anchor) -> dict | None:\n    """The anchor\'s event, normalised -- ``fires`` defaulting to `on_touch` and ``repeat`` to `edge` -- or None when\n    it carries none. A block that names an event outside the vocabulary, or a firing rule Dispatch does not know,\n    raises ValueError: a consumer could not read it the way it was meant."""\n    raw = anchor.extra.get("event") if hasattr(anchor, "extra") else None\n    if raw is None:\n        return None\n    if isinstance(raw, str):\n        raw = {"event": raw}\n    name = str(raw.get("event", ""))\n    if not name.startswith(EVENT_PREFIXES):\n        raise ValueError("anchor %s: event %r is not alarm.*, score.* or zone.*" % (anchor.id, name))\n    out = {"event": name, "fires": str(raw.get("fires", "on_touch")), "repeat": str(raw.get("repeat", "edge"))}\n    if out["fires"] not in EVENT_FIRES or out["repeat"] not in EVENT_REPEAT:\n        raise ValueError("anchor %s: event %r fires %r repeat %r" % (anchor.id, name, out["fires"], out["repeat"]))\n    if "audible" in raw:\n        out["audible"] = bool(raw["audible"])\n    for k in ("fixture", "room"):\n        if raw.get(k):\n            out[k] = str(raw[k])\n    return out\n\n\ndef required_authority_for(anchor: Anchor) -> str:\n')], 'dispatch/assembler.py': [('lines 22-22', 'from .anchors import find_duplicate_ids\n', 'from .anchors import event_block, find_duplicate_ids\n'), ('lines 188-189', '            md["objective"] = a.objective\n        scene.add(SceneNode(name=name, type="Marker3D", parent=parent,\n', '            md["objective"] = a.objective\n        ev = event_block(a)\n        if ev is not None:\n            md["event"] = ev\n        scene.add(SceneNode(name=name, type="Marker3D", parent=parent,\n')], 'dispatch/ownership.py': [('lines 11-11', 'from .anchors import (DEBUG_ANCHOR_TYPES, RUNTIME_OWNED_TYPES,\n', 'from .anchors import (DEBUG_ANCHOR_TYPES, RUNTIME_OWNED_TYPES, event_block,\n'), ('lines 130-133', '            "runtime_requirements": runtime_requirements_for(a),\n        })\n    return {\n        "schema": "dispatch.gameplay_anchors.v0.2",\n', '            "runtime_requirements": runtime_requirements_for(a),\n        })\n        # a gameplay event, where the anchor carries one (0.6.0; `anchors.event_block`)\n        ev = event_block(a)\n        if ev is not None:\n            items[-1]["event"] = ev\n    return {\n        "schema": "dispatch.gameplay_anchors.v0.2",\n')]}
